package portfolio.capstone;
import javafx.beans.property.*;
public final class Student { private final IntegerProperty id=new SimpleIntegerProperty(); private final StringProperty registrationNumber=new SimpleStringProperty(); private final StringProperty firstName=new SimpleStringProperty(); private final StringProperty lastName=new SimpleStringProperty(); public Student(){} public Student(int id,String reg,String first,String last){this.id.set(id);registrationNumber.set(reg);firstName.set(first);lastName.set(last);} public IntegerProperty idProperty(){return id;} public StringProperty registrationNumberProperty(){return registrationNumber;} public StringProperty firstNameProperty(){return firstName;} public StringProperty lastNameProperty(){return lastName;} public String getRegistrationNumber(){return registrationNumber.get();} public String getFirstName(){return firstName.get();} public String getLastName(){return lastName.get();} }
